# drafts/*.md 중 파일명 날짜(YYYY-MM-DD)가 가장 늦은 문서의 11~22줄 추출
$files = [self:file_find]{pattern: "drafts/*.md"} ?? [self:file_find]{path: "drafts", pattern: "*.md"} ?? [self:list]{path: "drafts", pattern: "*.md"}
$top = $files >> [table:sort]{by: "name", desc: true} >> [table:take]{n: 1}
$body = [self:read]{path: "${top.items.0.path}", start_line: 11, end_line: 22}
[self:mkdir]{path: "outputs"}
$body >> [self:write]{path: "outputs/latest_draft_lines.md"}
[self:read]{path: "${top.items.0.path}", start_line: 11, end_line: 22}

# drafts 폴더에서 파일명(YYYY-MM-DD)이 가장 늦은 문서의 11~22줄 읽기
$후보 = [self:file_find]{path: "drafts", pattern: "*.md"} ?? [self:file_find]{pattern: "drafts/*.md"}

# report_YYYY-MM-DD.md 형식은 사전순 = 날짜순이므로 경로 문자열 내림차순 첫 행이 최신 날짜
$최신 = $후보 >> [table:sort]{by: "path", desc: true} >> [table:take]{n: 1}

$결과 = $최신 >> [table:each]{keep: ["path"]} {
  $본문 = [self:read]{path: "${it.path}", start_line: 11, end_line: 22}
  $return = [{file: $it.path, lines: "11-22", content: $본문}]
}

$결과 >> [self:write]{path: "outputs/latest_draft_11_22.json", format: "json"}
$결과 >> [table:take]{n: 1}

# drafts/*.md 중 **파일명에 적힌 날짜**(YYYY-MM-DD)가 가장 늦은 문서의 11~22줄 본문
# 수정시각(mtime)은 기준이 아니다 — report_YYYY-MM-DD.md 는 사전순 = 날짜순이므로 name 내림차순 1건이 최신 날짜다.
$found = [self:file_find]{path: "drafts", pattern: "*.md"} ?? [self:file_find]{pattern: "drafts/*.md"}
$latest = $found >> [table:sort]{by: "name", desc: true} >> [table:take]{n: 1}
$target = $latest.items.0.path
$name = $latest.items.0.name

# 선정된 파일 하나를 직접 읽는다 (each 패스스루로 메타행이 흐르던 문제 제거)
$doc = [self:read]{path: "${target}", start_line: 11, end_line: 22}

# 결과 원장: items 봉투로 저장 (본문 원문 보존)
$doc >> [self:write]{path: "outputs/result.json", format: "json"}

$doc

# 1) 원본 registry.json 을 /tmp 에 백업 (작업 폴더 오염 없이 복구 지점 확보)
[self:read]{path: "registry.json"} >> [self:write]{path: "/tmp/registry_backup_merge.json", format: "json"}

# 2) 병합 전 두 파일의 실제 구조 확인 (지어내지 않고 읽어서 처리)
$updates_src = [self:read]{path: "updates.json"}

# 3) records 배열에 updates 행들을 id 기준 upsert
#    - 같은 id: 새로 온 필드만 덮어쓰고 기존 필드는 보존 (필드 단위 갱신)
#    - 없는 id: 새 행으로 추가
#    - records 밖의 메타데이터와 updates.json 원본은 건드리지 않음
[self:ledger]{op: "upsert", path: "registry.json", target: "records", key: "id", items_file: "updates.json"}

# 4) 결과 검증: 저장된 registry.json 과 변경되지 않아야 할 updates.json 을 다시 읽는다
$updates_after = [self:read]{path: "updates.json"}
[self:read]{path: "registry.json"}

# 1) 위치 목록 읽기 → 목록 순서대로 앞 3곳 → 끝줄(시작줄+4=5줄) 계산
$위치 = [self:read]{path: "locations.json"} >> [table:take]{n: 3}
$대상 = $위치 >> [table:compute]{set: {끝줄: "줄번호 + 4"}}

# 2) 각 위치에서 지정 줄부터 5줄 읽기 — 없는 파일은 그 위치와 오류를 행으로 남기고 나머지는 계속
$결과 = [table:each]{items: "$대상"} {
  [try]{
    $읽음 = [self:read]{path: "$it.파일", start_line: $it.줄번호, end_line: $it.끝줄}
    $return = [{파일: $it.파일, 줄번호: $it.줄번호, 본문: "$읽음", 오류: null}]
  }
  [catch]{
    $return = [{파일: $it.파일, 줄번호: $it.줄번호, 본문: null, 오류: "읽기 실패: ${error.summary?}"}]
  }
}

# 3) 결과 저장 + 반환 (파일·줄번호·본문·오류)
$결과 >> [self:write]{path: "outputs/위치별_본문.json", format: "json"}
$결과 >> [table:select]{columns: ["파일", "줄번호", "본문", "오류"]}

