# existing.json + arrivals.json → outputs/archive.json (id+kind 복합키, 선행 행 보존)
[self:mkdir]{path: "outputs"}
$옛것 = [self:read]{path: "existing.json"}
$새것 = [self:read]{path: "arrivals.json"}
[fn:원장에누적]{옛것: "$옛것", 새것: "$새것", 키: ["id", "kind"], 원장: "outputs/archive.json"}

# 1) 입력 두 파일을 통화(items)로 정규화해 읽는다 (배열/봉투 양쪽 대응, 원본은 읽기만)
$e = ([self:read]{path: "existing.json"} >> [table:take]{n: 100000}) ?? [self:ledger]{op: "select", path: "existing.json"}
$a = ([self:read]{path: "arrivals.json"} >> [table:take]{n: 100000}) ?? [self:ledger]{op: "select", path: "arrivals.json"}

[self:mkdir]{path: "outputs"}

# 2) 기존 + 신규 순서로 이어붙이고 (id, kind) 복합키로 첫 행(=기존 행 전체) 보존 중복 제거
$merged = $e.items & $a.items >> [table:union] >> [table:dedup]{by: ["id", "kind"]}

# 3) 보관
$merged >> [self:write]{path: "outputs/archive.json", format: "json"}

# 4) 확인용 미리보기 (열 이름·행 수 점검)
$merged >> [table:take]{n: 5}

# 수정 검토 자료 준비 — 입력은 읽기만 하고 산출은 outputs/ 에
[self:mkdir]{path: "outputs"}

$원본 = [self:read]{path: "review_locations.json"}

# 1) state=open, priority>=3 → 파일명 오름차순 → 앞 3곳의 지정 줄부터 5줄 본문 수집
$열림 = $원본 >> [table:filter]{where: "state == 'open' and priority >= 3"} >> [table:sort]{by: "파일"}
$열림 >> [fn:위치마다읽기]{개수: 3, 줄수: 5} >> [self:write]{path: "outputs/snippets.json", format: "json"}

# 2) state=closed 원래 행 전부 → 파일명 오름차순
$원본 >> [table:filter]{where: "state == 'closed'"} >> [table:sort]{by: "파일"} >> [self:write]{path: "outputs/closed.json", format: "json"}

# 입력 스키마 확인용 미리보기 (입력 파일은 변경하지 않음)
$원본 >> [table:take]{n: 2}

# 자료 반입 정리 — 승인분 아카이브 누적 + 반려분 별도 보관
[self:mkdir]{path: "outputs"}

$제출 = [self:read]{path: "submissions.json"}
$기존 = [self:read]{path: "existing.json"}

# 승인된 행만 id·kind·value 로 좁힌다 (원래 제출 순서 유지)
$승인 = $제출 >> [table:filter]{where: "approved == true"} >> [table:select]{columns: ["id", "kind", "value"]}

# 기존 행 먼저, 새 고유 행은 뒤에 — id+kind 복합키가 같으면 기존 행 전체 보존
[fn:원장에누적]{옛것: "$기존", 새것: "$승인", 키: ["id", "kind"], 원장: "outputs/archive.json"}

# 반려분은 원래 행 그대로 따로 보관 (입력 파일은 무변경)
$제출 >> [table:filter]{where: "approved == false"} >> [self:write]{path: "outputs/rejected.json", format: "json"}

# 자료 반입 정리 — 승인분 아카이브 + 반려분 별도 보관 (입력 파일 무변경)
[self:mkdir]{path: "outputs"}

$제출 = [self:read]{path: "submissions.json"}
$기존 = [self:read]{path: "existing.json"}

# 승인분: approved=true 행에서 id·kind·value 만 (제출 원래 순서 유지)
$승인 = $제출 >> [table:filter]{where: {field: "approved", op: "eq", value: true}} >> [table:select]{columns: ["id", "kind", "value"]}

# 기존 행 먼저 + 승인분 뒤에, (id, kind) 복합키 중복 시 기존 행 전체 보존
